/// <summary>
/// Controller of the overdue invoice notification batch job.
/// </summary>
public class DYLO_OverdueInvoiceNotificationController extends SysOperationServiceController
{
}

Method.Source:
public static DYLO_OverdueInvoiceNotificationController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    return new DYLO_OverdueInvoiceNotificationController(_executionMode);
}

public static void main(Args _args)
{
    DYLO_OverdueInvoiceNotificationController controller = DYLO_OverdueInvoiceNotificationController::construct();

    controller.parmArgs(_args);
    controller.startOperation();

    DYLO_OverdueInvoiceNotificationEmail::refreshCaller(_args);
}
